options.script:
if (!data || !data.series || data.series.length === 0 || !data.series[0].fields || data.series[0].fields.length < 2) {
    return { data: [], layout: { title: 'Sem dados para o filtro selecionado' } };
}

var valores = Array.from(data.series[0].fields[0].values);
var provedores = Array.from(data.series[0].fields[1].values);

var trace = {
    type: 'box',
    y: valores,
    x: provedores,
    name: 'Download (Mbps)',
    box: { visible: true },
    meanline: { visible: true },
    points: 'outliers',
    marker: { color: '#8e44ad', size: 3 },
    line: { color: '#8e44ad', width: 1.5 },
    fillcolor: 'rgba(142, 68, 173, 0.3)'
};

var layout = {
    title: 'Distribuicao de Download por Provedor',
    xaxis: { title: 'Provedor', type: 'category', automargin: true },
    yaxis: { title: 'Download (Mbps)', automargin: true },
    margin: { t: 40, r: 20, b: 60, l: 60 }
};

return { data: [trace], layout: layout };

